parameters.jsCode:
// 1. Get ALL historical rows from the Google Sheets lookup node.
// We use .all() to check the history, but we DO NOT pass this array forward.
const historyRows = $('HistoryCheck').all();

// 2. Get ONLY the current, new submission data.
// .first() is the magic command here. It ensures we only grab 1 item, 
// preventing any duplicate loops downstream.
const currentAI = $('parse the AI output').first().json;
const currentNormalized = $('node — normalize').first().json;

// 3. Evaluate if there is ANY previous negative feedback in the history.
// If historyRows is empty (new customer), this safely evaluates to false.
const isRepeatNegative = historyRows.some(item => {
  const score = Number(item.json.sentiment_score);
  return Number.isFinite(score) && score < 0;
});

// 4. Return EXACTLY ONE item. 
// This is the most important part to prevent double emails to staff/customers.
// Downstream nodes (Switch, Gmail, Sheets) will only see this single merged object.
return [{
  json: {
    // Flatten the normalized data (removes the 'body' wrapper if it exists)
    ...(currentNormalized.body || currentNormalized),

    // Add the AI analysis data (sentiment_score, severity, etc.)
    ...currentAI,

    // Add our custom boolean flag for the Switch node routing
    is_repeat_negative: isRepeatNegative
  }
}];

